-- Venue Live Guest "Ulang Tahun Little Chef". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara littlechef), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
