  $t${"name":"Little Chef","orn":"diamond","ui":{"ivory":"#FFF8F3","white":"#FFFFFF","soft":"#FBE0D8","soft2":"#F2A89A","accent":"#D32F2F","deep":"#7A1F1F","ink":"#5E2020","mute":"#A57B7B","line":"#F3D3CC","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFBF8","ink":"#5E2020","accent":"#D32F2F","gold":"#C9A24A","leaf":"#FBE0D8","hbg":"rgba(255,248,243,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(94,32,32,.9)","acc":"#FFD9A8","on":"#5E2020"},"scr":{"wine":"#7A1F1F","veil":"255,248,243"}}$t$::jsonb
